import AudioToolbox
import Foundation
import Synchronization
final class BinauralDSP {
    private let enabled = Atomic<UInt8>(0)
    private let amountBits = Atomic<UInt32>(Float(0.75).bitPattern)
    private var sampleRate: Float = 48_000
    private var channelCount = 0
    private var isFloat32 = false
    private var isNonInterleaved = false
    private var leftHistory: [Float] = []
    private var rightHistory: [Float] = []
    private var writeIndex = 0
    private var leftFarLP: Float = 0
    private var rightFarLP: Float = 0
    func setEnabled(_ value: Bool) { enabled.store(value ? 1 : 0, ordering: .relaxed) }
    func setAmount(_ value: Float) { amountBits.store(min(max(value, 0), 1).bitPattern, ordering: .relaxed) }
    func prepare(format: AudioStreamBasicDescription) {
        sampleRate = max(Float(format.mSampleRate), 8_000)
        channelCount = Int(format.mChannelsPerFrame)
        isFloat32 = format.mFormatID == kAudioFormatLinearPCM && (format.mFormatFlags & kAudioFormatFlagIsFloat) != 0 && format.mBitsPerChannel == 32
        isNonInterleaved = (format.mFormatFlags & kAudioFormatFlagIsNonInterleaved) != 0
        let historyFrames = max(128, Int(sampleRate * 0.002) + 8)
        leftHistory = Array(repeating: 0, count: historyFrames)
        rightHistory = Array(repeating: 0, count: historyFrames)
        writeIndex = 0; leftFarLP = 0; rightFarLP = 0
    }
    func unprepare() { writeIndex = 0; leftFarLP = 0; rightFarLP = 0 }
    func process(_ audioBufferList: UnsafeMutablePointer<AudioBufferList>, frames: Int) {
        guard frames > 0, channelCount == 2, isFloat32, !leftHistory.isEmpty, leftHistory.count == rightHistory.count else { return }
        let wetAmount: Float = enabled.load(ordering: .relaxed) == 0 ? 0 : Float(bitPattern: amountBits.load(ordering: .relaxed))
        let angleDegrees = 25 + 45 * wetAmount
        let theta = angleDegrees * .pi / 180
        let itdSeconds = (Float(0.0875) / 343) * (theta + sin(theta))
        let delayFrames = min(leftHistory.count - 1, max(1, Int(itdSeconds * sampleRate)))
        let cutoff = 7_000 - 3_800 * wetAmount
        let lpAlpha = 1 - exp(-2 * Float.pi * cutoff / sampleRate)
        let directGain: Float = 0.82, farGain: Float = 0.18, dryGain = 1 - wetAmount
        let buffers = UnsafeMutableAudioBufferListPointer(audioBufferList)
        if isNonInterleaved {
            guard buffers.count >= 2, let leftData = buffers[0].mData, let rightData = buffers[1].mData else { return }
            let left = leftData.assumingMemoryBound(to: Float.self), right = rightData.assumingMemoryBound(to: Float.self)
            for frame in 0..<frames { renderFrame(left: &left[frame], right: &right[frame], delayFrames: delayFrames, lpAlpha: lpAlpha, directGain: directGain, farGain: farGain, dryGain: dryGain, wetAmount: wetAmount) }
        } else {
            guard buffers.count >= 1, buffers[0].mNumberChannels >= 2, let data = buffers[0].mData else { return }
            let samples = data.assumingMemoryBound(to: Float.self)
            for frame in 0..<frames { let base = frame * 2; renderFrame(left: &samples[base], right: &samples[base + 1], delayFrames: delayFrames, lpAlpha: lpAlpha, directGain: directGain, farGain: farGain, dryGain: dryGain, wetAmount: wetAmount) }
        }
    }
    @inline(__always) private func renderFrame(left: inout Float, right: inout Float, delayFrames: Int, lpAlpha: Float, directGain: Float, farGain: Float, dryGain: Float, wetAmount: Float) {
        let inputL = left, inputR = right
        leftHistory[writeIndex] = inputL; rightHistory[writeIndex] = inputR
        var readIndex = writeIndex - delayFrames; if readIndex < 0 { readIndex += leftHistory.count }
        let delayedLeft = leftHistory[readIndex], delayedRight = rightHistory[readIndex]
        leftFarLP += lpAlpha * (delayedLeft - leftFarLP); rightFarLP += lpAlpha * (delayedRight - rightFarLP)
        let binauralL = directGain * inputL + farGain * rightFarLP
        let binauralR = directGain * inputR + farGain * leftFarLP
        left = dryGain * inputL + wetAmount * binauralL
        right = dryGain * inputR + wetAmount * binauralR
        writeIndex += 1; if writeIndex == leftHistory.count { writeIndex = 0 }
    }
}
